import React, { useEffect, useRef, memo } from 'react';

const TickerTape = () => {
  const containerRef = useRef(null);

  useEffect(() => {
    // Remove any previously injected widget
    if (!containerRef.current) return;
    containerRef.current.innerHTML = '';

    const widgetDiv = document.createElement('div');
    widgetDiv.className = 'tradingview-widget-container__widget';
    containerRef.current.appendChild(widgetDiv);

    const script = document.createElement('script');
    script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-ticker-tape.js';
    script.async = true;
    script.innerHTML = JSON.stringify({
      symbols: [
        { description: 'NIFTY 50',    proName: 'NSE:NIFTY'      },
        { description: 'SENSEX',      proName: 'BSE:SENSEX'     },
        { description: 'BANK NIFTY',  proName: 'NSE:BANKNIFTY'  },
        { description: 'Gold',        proName: 'TVC:GOLD'        },
        { description: 'Crude Oil',   proName: 'TVC:USOIL'       },
        { description: 'USD/INR',     proName: 'FX_IDC:USDINR'  },
      ],
      showSymbolLogo: true,
      isTransparent: false,
      displayMode: 'adaptive',
      colorTheme: 'light',
      locale: 'en',
    });

    containerRef.current.appendChild(script);
  }, []);

  return (
    <div
      className="tradingview-widget-container"
      ref={containerRef}
      style={{
        width: '100%',
        overflow: 'hidden',
        borderTop: '2px solid var(--accent-teal)',
        margin: '40px 0 20px 0',
      }}
    />
  );
};

export default memo(TickerTape);
